// ECHOLIVITY - IR browser / path helper.
// [js ech_ui.js]
// inlet:  lib <index>      library IR chosen in the IR menu (last item = "User IR")
//         user <path>      file dropped on the drop zone
//         restore <path>   user path restored from the Live Set (pattr)
// outlet 0: messages for buffer~ ---echIR   ("replace <path>")
// outlet 1: messages for the IR menu        ("set <index>")
// outlet 2: status text
// outlet 3: user path to store (pattr)

autowatch = 1;
inlets = 1;
outlets = 4;

// keep in sync with ir/catalogue.json (generated by tools/build_device.py)
var LIB = __LIB__;
var userPath = "";

function root() {
	var p = this.patcher.filepath || "";
	var i = p.lastIndexOf("/");
	p = p.substring(0, i);               // .../device
	i = p.lastIndexOf("/");
	return p.substring(0, i);            // project root
}

function lib(i) {
	i = Math.floor(i);
	if (i < LIB.length) {
		var path = root() + "/ir/processed/" + LIB[i] + "__norm48k.wav";
		outlet(0, "replace", path);
		outlet(2, "set", LIB[i] + (LIB[i].indexOf("SYN_") === 0 ? "  (synthetic)" : "  (third-party IR)"));
	} else if (userPath !== "") {
		outlet(0, "replace", userPath);
		outlet(2, "set", "User: " + userPath.substring(userPath.lastIndexOf("/") + 1));
	} else {
		outlet(2, "set", "Drop a WAV on the IR zone");
	}
}

function user(p) {
	userPath = String(p);
	outlet(3, userPath);
	outlet(1, "set", LIB.length);
	lib(LIB.length);
}

function restore(p) {
	if (p && String(p) !== "" && String(p) !== "0") userPath = String(p);
}

function anything() {
	// live.drop sends a bare path symbol
	if (messagename && messagename.indexOf("/") >= 0) user(messagename);
}
